<?php
namespace App\Http\Controllers;
use App\Models\Product; use App\Models\Sale; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class SaleController extends Controller {public function index():View{return view('sales.index',['sales'=>Sale::with('product')->latest('sold_at')->paginate(12)]);}public function create():View{return view('sales.create',['products'=>Product::where('quantity','>',0)->orderBy('name')->get()]);}public function store(Request $r):RedirectResponse{$data=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1','sold_at'=>'required|date']);DB::transaction(function()use($data):void{$product=Product::whereKey($data['product_id'])->lockForUpdate()->firstOrFail();if($product->quantity<$data['quantity'])throw \Illuminate\Validation\ValidationException::withMessages(['quantity'=>'Not enough stock for this sale.']);$product->decrement('quantity',$data['quantity']);Sale::create(['product_id'=>$product->id,'quantity'=>$data['quantity'],'unit_price'=>$product->unit_price,'sold_at'=>$data['sold_at']]);});return redirect()->route('sales.index')->with('success','Sale recorded and stock updated.');}public function destroy(Sale $sale):RedirectResponse{DB::transaction(function()use($sale):void{$sale->product()->increment('quantity',$sale->quantity);$sale->delete();});return redirect()->route('sales.index')->with('success','Sale removed and stock restored.');}}
